48	const PROCESSING_FEE = 5;
49	const FIRST_INSURANCE_SURCHARGE = 0.1;
50	
51	const BASE_PREMIUMS: Record<string, number> = {
52	  sword: 100,
53	  amulet: 60,
54	  staff: 80,
55	  potion: 40,
56	  rune: 25,
57	  moonstone: 25,
58	};
59	
60	/** Premiums are rounded up — in MHPCO's favour. */
61	const roundPremium = (amount: number): number => Math.ceil(amount);
62	
63	const COMPONENT_BLOCK_SIZE = 3;
64	const COMPONENT_BLOCK_PREMIUM = 60;
65	
66	const sumOfItemBasePremiums = (items: Item[]): number =>
67	  items.reduce((sum, item) => sum + BASE_PREMIUMS[item.type], 0);
68	
69	const formsRuneBlock = (items: Item[]): boolean =>
70	  items.filter((item) => item.type === "rune").length === COMPONENT_BLOCK_SIZE;
71	
72	const policyBasePremiumFor = (items: Item[]): number =>
73	  formsRuneBlock(items) ? COMPONENT_BLOCK_PREMIUM : sumOfItemBasePremiums(items);
74	
75	const quotePremium = (items: Item[]): number => {
76	  const policyBasePremium = policyBasePremiumFor(items);
77	  const firstInsuranceSurcharge = policyBasePremium * FIRST_INSURANCE_SURCHARGE;
78	  return roundPremium(
79	    policyBasePremium + firstInsuranceSurcharge + PROCESSING_FEE,
80	  );
81	};
82	
83	const runStep = (step: Step): StepResult => {
84	  if (step.op === "quote") {
85	    return { premium: quotePremium(step.items) };
86	  }
87	  throw new Error(`Unsupported step: ${step.op}`);
88	};
89	
90	export const runScenario = (scenario: Scenario): ScenarioResult => ({
91	  results: scenario.steps.map(runStep),
92	});
