const BASE_PREMIUMS = {
  sword: 100,
  amulet: 60,
  staff: 80,
  potion: 40,
  rune: 25,
  moonstone: 25,
} as const satisfies Record<string, number>;

type InsurableItemType = keyof typeof BASE_PREMIUMS;

const basePremiumOf = (item: Item): number =>
  BASE_PREMIUMS[item.type as InsurableItemType];
